losses=((F(0),F(80,100)),(F(10),F(15,100)),(F(100),F(5,100)))
alpha=F(95,100)
cdf=sum((p for loss,p in losses if loss<=10),F(0))
var=F(10)
def cvar_objective(eta):
    return eta+sum((p*max(loss-eta,F(0)) for loss,p in losses),F(0))/(1-alpha)
es=cvar_objective(var)
assert cdf==alpha and es==100
assert cvar_objective(F(100))==100 and cvar_objective(F(0))==130
for eta in (F(10),F(20),F(50),F(100)):
    assert cvar_objective(eta)==100
EXPECTED={'value_at_risk_95':var,'expected_shortfall_95':es,'cvar_objective_at_var':es}
